/**
 * Writes scripts/data/thiqa-obesity-reimbursement-abu-dhabi.json with every Sanity
 * blogPost field filled from the hardcoded SSR module.
 *
 * Cover / hero JPEGs are generated by scripts/generate-thiqa-obesity-cover.mjs.
 *
 *   node scripts/generate-thiqa-obesity-sanity-json.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createServer } from 'vite';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const outPath = path.join(root, 'scripts/data/thiqa-obesity-reimbursement-abu-dhabi.json');

export const ANNA_CUBAN_SANITY_ID = '7acabff7-aae6-4d8a-a667-91e21a235bcb';

/** Every blogPost field that applies to a healthcare-silo article. */
export const THIQA_OBESITY_SANITY_FIELDS = [
  'seo',
  'openGraph',
  'title',
  'slug',
  'excerpt',
  'publishedAt',
  'updatedAt',
  'author',
  'mainImage',
  'categories',
  'category',
  'contentSilo',
  'tags',
  'country',
  'language',
  'readingTime',
  'executiveSummary',
  'tableOfContents',
  'bodyHtml',
  'body',
  'faq',
  'relatedPostSlugs',
  'ctaSection',
  'sources',
  'factCheckedAt',
];

function stripHtml(html) {
  return String(html)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function portableText(text) {
  return {
    _type: 'block',
    style: 'normal',
    children: [{ _type: 'span', marks: [], text }],
    markDefs: [],
  };
}

function extractSources(bodyHtml) {
  return [...bodyHtml.matchAll(/<li id="ref-[^"]+">([\s\S]*?)<\/li>/g)].map((match) =>
    stripHtml(match[1]),
  );
}

async function loadArticle() {
  const vite = await createServer({
    root,
    server: { middlewareMode: true },
    appType: 'custom',
    logLevel: 'error',
  });
  try {
    return await vite.ssrLoadModule('/src/data/blog-thiqa-obesity-reimbursement-abu-dhabi.ts');
  } finally {
    await vite.close();
  }
}

export function buildSanityPayload(mod) {
  const shortAnswer = stripHtml(mod.THIQA_OBESITY_EXECUTIVE_SUMMARY_HTML).replace(
    /^Short answer:\s*/i,
    '',
  );
  const firstParagraph = stripHtml(mod.THIQA_OBESITY_BODY_HTML.split('<h2')[0])
    .replace(/^Thiqa obesity reimbursement[\s\S]*?This briefing uses only published sources\./, '')
    .trim();

  return {
    seo: {
      metaTitle: mod.THIQA_OBESITY_META_TITLE,
      metaDescription: mod.THIQA_OBESITY_META_DESCRIPTION,
      focusKeyword: 'Thiqa obesity reimbursement',
      keywords: [
        'Thiqa obesity reimbursement',
        'Abu Dhabi GLP-1 coverage',
        'obesity market research UAE',
        'Thiqa GLP-1',
        'DOH obesity medication policy',
        'Abu Dhabi obesity reimbursement',
        'Sahatna weight management',
        'UAE market access obesity',
      ],
      canonicalUrl: mod.THIQA_OBESITY_URL,
      noIndex: false,
    },
    openGraph: {
      ogTitle: mod.THIQA_OBESITY_META_TITLE,
      ogDescription: mod.THIQA_OBESITY_META_DESCRIPTION,
      ogImage: {
        path: `public${mod.THIQA_OBESITY_COVER_IMAGE}`,
        alt: mod.THIQA_OBESITY_COVER_IMAGE_ALT,
        geminiPending: false,
      },
    },
    title: mod.THIQA_OBESITY_DISPLAY_TITLE,
    slug: { _type: 'slug', current: mod.THIQA_OBESITY_SLUG },
    excerpt: mod.THIQA_OBESITY_EXCERPT,
    publishedAt: mod.THIQA_OBESITY_PUBLISHED_ISO,
    updatedAt: mod.THIQA_OBESITY_UPDATED_ISO,
    author: {
      _type: 'reference',
      _ref: ANNA_CUBAN_SANITY_ID,
      name: 'Anna Cuban',
      jobTitle: 'Global Research Manager',
    },
    mainImage: {
      path: `public${mod.THIQA_OBESITY_HERO_IMAGE}`,
      alt: mod.THIQA_OBESITY_HERO_IMAGE_ALT,
      caption: 'BioNixus-branded hero for Thiqa obesity reimbursement in Abu Dhabi',
      geminiPending: false,
    },
    categories: [{ title: 'Healthcare Market Research' }],
    category: 'Healthcare Market Research',
    contentSilo: 'healthcare',
    tags: [...mod.THIQA_OBESITY_TAGS],
    country: 'United Arab Emirates',
    language: 'en',
    readingTime: mod.THIQA_OBESITY_READING_TIME,
    executiveSummary: [portableText(shortAnswer)],
    tableOfContents: mod.THIQA_OBESITY_TABLE_OF_CONTENTS.map((item) => ({
      heading: item.heading,
      anchor: item.anchor,
    })),
    bodyHtml: `${mod.THIQA_OBESITY_EXECUTIVE_SUMMARY_HTML}\n\n${mod.THIQA_OBESITY_BODY_HTML}`,
    body: [
      {
        _type: 'callout',
        type: 'insight',
        title: 'Short answer',
        content: shortAnswer,
      },
      {
        _type: 'dataVisualization',
        title: 'What obesity market research UAE should measure after Thiqa obesity reimbursement',
        type: 'table',
        data: JSON.stringify(
          mod.THIQA_OBESITY_WORKSTREAMS.map((stream) => ({
            name: stream.name,
            researchType: stream.researchType,
            question: stream.question,
          })),
        ),
        source: 'DOH Thiqa OMM policy, 11 June 2025; DOH non-surgical standard, February 2025; UAE NHS 2017–18',
      },
      portableText(
        firstParagraph ||
          'Thiqa obesity reimbursement is an access problem before it is a sizing problem.',
      ),
    ],
    faq: mod.THIQA_OBESITY_FAQ.map((item) => ({
      question: item.question,
      answer: item.answer,
    })),
    relatedPostSlugs: ['obesity-market-research-kuwait', 'qatar-obesity-glp1-market-research'],
    ctaSection: { ...mod.THIQA_OBESITY_HARDCODED_POST.ctaSection },
    sources: extractSources(mod.THIQA_OBESITY_BODY_HTML),
    factCheckedAt: mod.THIQA_OBESITY_UPDATED_ISO,
    geminiCoverPending: false,
    coverNote:
      'mainImage and openGraph.ogImage are the Playwright-rendered BioNixus JPEGs at public/images/blog/thiqa-obesity-reimbursement-abu-dhabi-{hero,cover}.jpg.',
  };
}

async function main() {
  const mod = await loadArticle();
  const payload = buildSanityPayload(mod);
  for (const field of THIQA_OBESITY_SANITY_FIELDS) {
    if (payload[field] == null) {
      throw new Error(`Sanity payload missing field: ${field}`);
    }
  }
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, `${JSON.stringify(payload, null, 2)}\n`);
  console.log(`Wrote ${path.relative(root, outPath)} (${payload.sources.length} sources, bodyHtml ${payload.bodyHtml.length} chars)`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
